window.OVA_CONTENT={"slug":"seccion-05-fisiologia-animal-y-gestion","title":"Fisiología animal y gestión productiva","minutes":50,"summary":"Interpreta digestión, respiración, circulación, metabolismo, bienestar y ambiente en sistemas ganaderos y avícolas.","objective":"Relacionar funciones fisiológicas con indicadores de manejo y desempeño animal.","stages":[{"eyebrow":"Sistemas","title":"1. Funciones que trabajan juntas","reading":"La digestión libera nutrientes; la respiración permite intercambio gaseoso; la circulación distribuye sustancias; el metabolismo integra reacciones de mantenimiento, crecimiento y producción.","application":"Un indicador productivo refleja la interacción entre sistemas, alimentación, ambiente, salud y manejo.","activity":{"type":"match","question":"Relaciona sistema y función principal.","pairs":[{"label":"Digestivo","value":"nutrientes","option":"Obtener nutrientes absorbibles"},{"label":"Respiratorio","value":"gases","option":"Intercambiar gases"},{"label":"Circulatorio","value":"distribuir","option":"Distribuir sustancias"}],"answer":["nutrientes","gases","distribuir"],"success":"Los sistemas se complementan."}},{"eyebrow":"Metabolismo","title":"2. Energía para mantener y producir","reading":"El organismo distribuye la energía disponible entre mantenimiento, actividad, termorregulación, crecimiento y producción. Si aumenta el costo de mantener la temperatura, puede disminuir la energía destinada al producto.","application":"La gestión debe interpretar consumo, conversión y producción junto con las condiciones ambientales.","activity":{"type":"choice","question":"Durante estrés térmico, ¿qué cambio es plausible?","options":["Más energía dedicada a termorregulación","Mayor partición de energía hacia crecimiento aunque disminuya el consumo","Menor gasto de mantenimiento debido al aumento de temperatura corporal"],"answer":[0],"success":"El balance energético responde al ambiente."}},{"eyebrow":"Manejo","title":"3. Variables que modifican el desempeño","reading":"Calidad de dieta, acceso al agua, densidad, ventilación, temperatura, sanidad y bienestar influyen sobre el funcionamiento fisiológico. La especie y la etapa productiva cambian los rangos esperados.","application":"Comparar indicadores sin contexto puede llevar a decisiones erróneas. La organización debe registrar condiciones, controles y resultados para convertir el conocimiento biológico en una decisión productiva verificable.","activity":{"type":"multi","question":"Selecciona variables de manejo relevantes.","options":["Disponibilidad de agua","Ventilación efectiva","Densidad animal","Fecha de compra del alimento sin información de composición"],"answer":[0,1,2],"success":"Las condiciones de manejo afectan la respuesta biológica."}},{"eyebrow":"Interpretación","title":"4. Del indicador a la decisión","reading":"Una baja en producción puede tener causas nutricionales, ambientales, sanitarias o de registro. Conviene verificar datos, observar patrones y solicitar valoración especializada cuando corresponda.","application":"La biología apoya la gestión, pero no sustituye el diagnóstico veterinario o zootécnico. La organización debe registrar condiciones, controles y resultados para convertir el conocimiento biológico en una decisión productiva verificable.","activity":{"type":"order","question":"Ordena un análisis prudente.","items":["Confirmar el indicador","Revisar ambiente y manejo","Comparar consumo y salud","Consultar valoración especializada","Aplicar y monitorear medidas"],"answer":[0,1,2,3,4],"success":"La decisión sigue evidencia y competencias profesionales."}},{"eyebrow":"Caso aplicado","title":"5. Galpón con alta temperatura","reading":"En un galpón aumentan la temperatura y la humedad, disminuye el consumo y baja la ganancia de peso. La ventilación funciona de manera irregular. Su interpretación exige comparar condiciones, escalas y registros, porque una observación aislada no demuestra causalidad ni permite predecir por sí sola el resultado productivo.","application":"La relación entre ambiente, termorregulación y consumo ofrece una hipótesis que debe verificarse.","activity":{"type":"choice","question":"¿Qué medida inicial es más coherente?","options":["Restablecer ventilación, medir condiciones y seguir indicadores","Cambiar la dieta y comparar peso al final sin registrar el ambiente","Seleccionar animales de mayor ganancia antes de verificar la falla de ventilación"],"answer":[0],"success":"Controlar y medir el ambiente permite evaluar la respuesta."}},{"eyebrow":"Homeostasis","title":"6. Mantener el medio interno tiene un costo","reading":"La homeostasis regula temperatura, agua, pH y glucosa dentro de rangos compatibles con la función. Cuando el ambiente exige mayor regulación, cambia el uso de energía.","application":"Indicadores productivos deben leerse junto con conducta, temperatura, consumo y signos clínicos.","visual":{"label":"Mantener el medio interno tiene un costo","items":["Ambiente","Respuesta","Consumo","Producción"]},"activity":{"type":"choice","question":"¿Cuál patrón apoya una hipótesis de estrés térmico?","options":["Mayor jadeo, menor consumo y caída productiva durante horas de alta carga térmica","Baja productiva constante con ambiente estable y sin cambios conductuales","Mayor consumo acompañado de temperatura corporal dentro del rango habitual"],"answer":[0],"success":"La coincidencia temporal entre ambiente, respuesta fisiológica y desempeño fortalece la hipótesis."}},{"eyebrow":"Bienestar","title":"7. Indicadores que se complementan","reading":"El bienestar no se resume en un único dato. Se combinan indicadores basados en recursos, manejo y estado del animal. Su interpretación exige comparar condiciones, escalas y registros, porque una observación aislada no demuestra causalidad ni permite predecir por sí sola el resultado productivo.","application":"Buena infraestructura no garantiza por sí sola bienestar si la conducta, salud o acceso efectivo muestran problemas.","activity":{"type":"multi","question":"¿Qué conjunto aporta evidencia directa o contextual sobre bienestar?","options":["Lesiones y condición corporal","Conducta y acceso efectivo a recursos","Calidad del ambiente y prácticas de manejo","Producción máxima como único criterio"],"answer":[0,1,2],"success":"La evaluación combina resultados en el animal y condiciones que los explican."}},{"eyebrow":"Intervención","title":"8. Probar una mejora de manejo","reading":"Una intervención debe definir población, cambio, indicadores, comparación y periodo. También debe vigilar efectos no previstos. Su interpretación exige comparar condiciones, escalas y registros, porque una observación aislada no demuestra causalidad ni permite predecir por sí sola el resultado productivo.","application":"Modificar ventilación o dieta sin línea base impide atribuir con confianza cualquier cambio observado.","activity":{"type":"order","question":"Ordena la evaluación de una mejora productiva.","items":["Establecer línea base e indicadores","Definir intervención y grupo comparable","Implementar con registro de cumplimiento","Medir respuesta fisiológica y productiva","Comparar, ajustar y documentar"],"answer":[0,1,2,3,4],"success":"La evaluación permite distinguir una mejora real de una variación temporal."}}],"number":"05","references":["Audesirk, T. et al. (2017). Biología: La vida en la tierra con fisiología. Pearson Educación.","Freeman, S. (2009). Biología. Pearson Educación.","Gutiérrez Ramírez, L. A. (2016). Los microorganismos en la agroindustria. Editorial Lasallista.","Mader, S. S. (2024). Biología. McGraw-Hill.","Velázquez Ocampo, M. P. (2020). Biología II. Cengage Learning."]};